const menuIcons = [Home, Hospital, Users, Stethoscope, UserRound, Building2, CalendarDays, ClipboardList, Bed, AlertTriangle, Activity, FlaskConical, Pill, Package, Wallet, ShieldCheck, Users, Activity, LockKeyhole, Settings];
const collectionBySection: Partial<Record<AdminSection, keyof AdminData>> = {
  departments: 'departments', users: 'users', doctors: 'doctors', patients: 'patients',
  appointments: 'appointments', admissions: 'admissions', beds: 'beds', emergency: 'emergencies',
  theatre: 'theatre', laboratory: 'laboratory', pharmacy: 'pharmacy', inventory: 'inventory',
  billing: 'invoices', insurance: 'insurance', hr: 'hr',
};

function loadAdminData(key: string): AdminData {
  try {
    const saved = localStorage.getItem(key);
    return saved ? { ...seedData, ...JSON.parse(saved) as Partial<AdminData> } : seedData;
  } catch {
    return seedData;
  }
}

function loadAdminSetting<T,>(key: string, fallback: T): T {
  try {
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) as T : fallback;
  } catch {
    return fallback;
  }
}

export function AdminCommandPortal({ name, email, language, onToggleLanguage, onLogout }: AdminCommandPortalProps) {
  const t = copy[language] as Record<string, string>;
  const dataKey = `carepulse.admin.${email}.data`;
  const [section, setSection] = useState<AdminSection>('overview');
  const [data, setData] = useState<AdminData>(() => loadAdminData(dataKey));
  const [query, setQuery] = useState('');
  const [notice, setNotice] = useState('');
  const [mobileNav, setMobileNav] = useState(false);
  const [formName, setFormName] = useState('');
  const [formDetail, setFormDetail] = useState('');
  const [hospital, setHospital] = useState(() => loadAdminSetting(`${dataKey}.hospital`, { name: 'CarePulse Hospital', address: '24 CarePulse Avenue, Dhaka 1212', phone: '+880 1712-345678', email: 'hello@carepulse.bd', emergency: '16263 / 999', website: 'www.carepulse.bd', logo: 'CarePulse mark' }));
  const [facilities, setFacilities] = useState(() => loadAdminSetting(`${dataKey}.facilities`, ['ICU', 'Emergency', 'Operation Theatre', 'Pharmacy', 'Laboratory', 'Ambulance', 'Blood Bank']));
  const [permissionToggles, setPermissionToggles] = useState<Record<string, boolean>>(() => loadAdminSetting(`${dataKey}.permissions`, { 'Doctor: clinical records': true, 'Doctor: financial reports': false, 'Nurse: assigned patients': true, 'Accountant: billing ledger': true, 'Accountant: medical records': false, 'Receptionist: registration': true, 'Lab staff: reports': true, 'Pharmacy: dispensing': true }));
  const [twoFactor, setTwoFactor] = useState(() => loadAdminSetting(`${dataKey}.twoFactor`, true));
  const [timeout, setTimeout] = useState(() => loadAdminSetting(`${dataKey}.timeout`, true));
  const [aiQuestion, setAiQuestion] = useState('');
  const [aiAnswer, setAiAnswer] = useState('');
  const [audit, setAudit] = useState<{ action: string; time: string }[]>([
    { action: 'Reception registered PT-1001 · Rahim Uddin', time: 'Today · 09:12' }, { action: 'Lab uploaded CBC report · LAB-2081', time: 'Today · 08:54' }, { action: 'Accountant recorded payment · INV-2026-103', time: 'Yesterday · 16:38' },
  ]);

  useEffect(() => { localStorage.setItem(dataKey, JSON.stringify(data)); }, [data, dataKey]);
  useEffect(() => { localStorage.setItem(`${dataKey}.hospital`, JSON.stringify(hospital)); }, [dataKey, hospital]);
  useEffect(() => { localStorage.setItem(`${dataKey}.facilities`, JSON.stringify(facilities)); }, [dataKey, facilities]);
  useEffect(() => { localStorage.setItem(`${dataKey}.permissions`, JSON.stringify(permissionToggles)); }, [dataKey, permissionToggles]);
  useEffect(() => { localStorage.setItem(`${dataKey}.twoFactor`, JSON.stringify(twoFactor)); }, [dataKey, twoFactor]);
  useEffect(() => { localStorage.setItem(`${dataKey}.timeout`, JSON.stringify(timeout)); }, [dataKey, timeout]);

  const heading = t[sections.find((entry) => entry.key === section)?.label ?? 'overview'];
  const notify = (message: string) => { setNotice(message); setAudit((current) => [{ action: message, time: 'Just now' }, ...current].slice(0, 12)); window.setTimeout(() => setNotice(''), 3200); };
  const go = (key: AdminSection) => { setSection(key); setQuery(''); setNotice(''); setMobileNav(false); };
  const currentRecords: Row[] = section === 'departments' ? data.departments : section === 'users' ? data.users : section === 'doctors' ? data.doctors : section === 'patients' ? data.patients : section === 'appointments' ? data.appointments : section === 'admissions' ? data.admissions : section === 'beds' ? data.beds : section === 'emergency' ? data.emergencies : section === 'theatre' ? data.theatre : section === 'laboratory' ? data.laboratory : section === 'pharmacy' ? data.pharmacy : section === 'inventory' ? data.inventory : section === 'billing' ? data.invoices : section === 'insurance' ? data.insurance : section === 'hr' ? data.hr : [];
  const filteredRecords = useMemo(() => currentRecords.filter((record) => `${record.id} ${record.name} ${record.detail} ${record.status}`.toLowerCase().includes(query.toLowerCase())), [currentRecords, query]);
  const activeBeds = data.beds.filter((bed) => bed.status === 'Occupied').length;
  const freeBeds = data.beds.filter((bed) => bed.status === 'Available').length;
  const pendingInvoices = data.invoices.filter((invoice) => invoice.status !== 'Paid').length;
  const lowStock = data.pharmacy.filter((medicine) => medicine.status === 'Low stock').length + data.inventory.filter((item) => item.status === 'Low stock').length;

  const addRecord = (event: FormEvent) => {
    event.preventDefault();
    if (!formName.trim()) return;
    const newRow: Row = { id: `NEW-${Date.now().toString().slice(-5)}`, name: formName.trim(), detail: formDetail.trim() || `${t.created} · ${name}`, status: section === 'appointments' ? 'Pending approval' : section === 'beds' ? 'Available' : section === 'billing' ? 'Pending' : 'Active', amount: section === 'billing' ? 0 : undefined };
    const target = section === 'departments' ? 'departments' : section === 'users' ? 'users' : section === 'doctors' ? 'doctors' : section === 'patients' ? 'patients' : section === 'appointments' ? 'appointments' : section === 'admissions' ? 'admissions' : section === 'beds' ? 'beds' : section === 'emergency' ? 'emergencies' : section === 'theatre' ? 'theatre' : section === 'laboratory' ? 'laboratory' : section === 'pharmacy' ? 'pharmacy' : section === 'inventory' ? 'inventory' : section === 'billing' ? 'invoices' : section === 'insurance' ? 'insurance' : 'hr';
    setData((current) => ({ ...current, [target]: [newRow, ...current[target]] }));
    setFormName(''); setFormDetail(''); notify(t.created);
  };

  const updateRecord = (id: string, changes?: Partial<Row>) => {
    const target = section === 'departments' ? 'departments' : section === 'users' ? 'users' : section === 'doctors' ? 'doctors' : section === 'patients' ? 'patients' : section === 'appointments' ? 'appointments' : section === 'admissions' ? 'admissions' : section === 'beds' ? 'beds' : section === 'emergency' ? 'emergencies' : section === 'theatre' ? 'theatre' : section === 'laboratory' ? 'laboratory' : section === 'pharmacy' ? 'pharmacy' : section === 'inventory' ? 'inventory' : section === 'billing' ? 'invoices' : section === 'insurance' ? 'insurance' : 'hr';
    setData((current) => ({ ...current, [target]: current[target].flatMap((record) => {
      if (record.id !== id) return [record];
      if (changes?.status === 'Archived') return [];
      if (changes) return [{ ...record, ...changes }];
      const status = record.status;
      const next = section === 'billing' && status === 'Paid' ? 'Refund requested' : section === 'doctors' && status === 'Available' ? 'On leave' : section === 'doctors' && status === 'On leave' ? 'Available' : section === 'admissions' && status === 'Active' ? 'Discharged' : section === 'emergency' && status === 'Critical' ? 'Under review' : status === 'Pending approval' ? 'Confirmed' : status === 'Pending collection' ? 'Processing' : status === 'Processing' ? 'Completed' : status === 'Available' ? 'Reserved' : status === 'Reserved' ? 'Occupied' : status === 'Occupied' ? 'Cleaning' : status === 'Cleaning' ? 'Available' : status === 'Pending' ? 'Paid' : status === 'Submitted' || status === 'Under review' ? 'Approved' : status === 'Active' ? 'Inactive' : status === 'Low stock' ? 'Reorder placed' : status === 'En route' ? 'Arrived' : status === 'Preparing' || status.startsWith('Scheduled') ? 'In progress' : status === 'In progress' ? 'Completed' : status === 'Present' ? 'Leave pending' : 'Reviewed';
      return [{ ...record, status: next }];
    }) }));
    notify(changes?.status === 'Archived' ? (language === 'en' ? 'Record removed from active management.' : 'সক্রিয় ব্যবস্থাপনা থেকে রেকর্ড সরানো হয়েছে।') : changes ? t.updated : t.updated);
  };

  const saveRecord = (id: string, recordName: string, detail: string) => {
    const target = collectionBySection[section];
    if (!target) return;
    setData((current) => ({ ...current, [target]: current[target].map((record) => record.id === id ? { ...record, name: recordName, detail } : record) }));
    notify(t.updated);
  };

  const removeRecord = (id: string) => {
    const target = collectionBySection[section];
    if (!target) return;
    setData((current) => ({ ...current, [target]: current[target].filter((record) => record.id !== id) }));
    notify(language === 'en' ? 'Administrative record removed.' : 'প্রশাসনিক রেকর্ড সরানো হয়েছে।');
  };

  const assignRole = (id: string, role: string) => {
    setData((current) => ({ ...current, users: current.users.map((record) => record.id === id ? { ...record, detail: `${role} · ${record.detail.split('·').slice(1).join('·').trim()}` } : record) }));
    notify(t.roleChanged);
  };

  const statusLabel = (status: string) => language === 'bn' ? ({ Active: 'সক্রিয়', Inactive: 'নিষ্ক্রিয়', 'On leave': 'ছুটিতে', Discharged: 'ছাড়পত্র সম্পন্ন', 'Refund requested': 'রিফান্ড অনুরোধ', Available: t.available, Occupied: t.occupied, Cleaning: t.cleaning, Reserved: t.reserved, 'Pending approval': 'অনুমোদন বাকি', Confirmed: 'নিশ্চিত', Waiting: 'অপেক্ষমাণ', Cancelled: 'বাতিল', 'Low stock': t.lowStock, Processing: 'প্রক্রিয়াধীন', 'Pending collection': 'নমুনা বাকি', Completed: 'সম্পন্ন', Paid: t.paid, Pending: t.pending, Partial: 'আংশিক', Submitted: 'জমা হয়েছে', 'Under review': 'পর্যালোচনাধীন', Approved: 'অনুমোদিত', Critical: t.critical, 'En route': 'পথে আছে', Preparing: 'প্রস্তুতি চলছে', Present: 'উপস্থিত', 'Leave pending': 'ছুটি বাকি', 'Maintenance due': 'রক্ষণাবেক্ষণ বাকি', 'Reorder placed': 'পুনঃঅর্ডার হয়েছে', Arrived: 'পৌঁছেছে', 'In progress': 'চলমান', Reviewed: 'পর্যালোচিত', 'Scheduled · 14:00': 'নির্ধারিত · ১৪:০০', 'Ready for review': 'পর্যালোচনার জন্য প্রস্তুত' } as Record<string, string>)[status] ?? status : status;

  const decideAssistant = (event: FormEvent) => {
    event.preventDefault();
    const question = aiQuestion.toLowerCase();
    setAiAnswer(question.includes('revenue') || question.includes('রাজস্ব') ? t.aiRevenue : question.includes('department') || question.includes('বিভাগ') ? t.aiLoad : question.includes('bed') || question.includes('বেড') ? t.aiBeds : question.includes('stock') || question.includes('medicine') || question.includes('স্টক') ? t.aiStock : t.aiFallback);
    setAiQuestion('');
  };

  const rowActionLabel = (row: Row) => section === 'doctors' ? (row.status === 'Available' ? (language === 'en' ? 'Schedule leave' : 'ছুটি নির্ধারণ') : (language === 'en' ? 'Mark available' : 'উপলব্ধ করুন')) : row.status === 'Pending approval' ? t.approve : row.status === 'Available' ? t.reserve : row.status === 'Occupied' || (section === 'admissions' && row.status === 'Active') ? t.discharge : row.status === 'Paid' ? t.refund : row.status === 'Low stock' ? t.action : row.status === 'Active' ? t.action : row.status === 'Present' ? t.leave : t.action;

  return (
    <div className="min-h-screen bg-[#f3f7fa] text-slate-900 lg:flex">
      <aside className={`${mobileNav ? 'block' : 'hidden'} fixed inset-0 z-40 bg-white lg:sticky lg:top-0 lg:block lg:h-screen lg:w-[278px] lg:shrink-0 lg:border-r lg:border-slate-200`}>
        <div className="flex items-center justify-between border-b border-slate-200 px-5 py-5"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-800 text-white"><Hospital className="h-5 w-5"/></span><span><b className="block">CarePulse</b><small className="text-xs text-slate-500">Hospital command center</small></span></div><button onClick={() => setMobileNav(false)} className="rounded-lg p-2 lg:hidden" aria-label={t.close}><X className="h-5 w-5"/></button></div>
        <div className="flex items-center gap-3 border-b border-slate-200 px-5 py-4"><span className="grid h-10 w-10 place-items-center rounded-full bg-blue-50 font-bold text-blue-800">{name.split(' ').map((part) => part[0]).slice(0, 2).join('')}</span><div className="min-w-0"><b className="block truncate text-sm">{name}</b><small className="text-xs text-slate-500">{email}</small></div><ShieldCheck className="ml-auto h-4 w-4 text-blue-700"/></div>
        <nav className="h-[calc(100vh-150px)] overflow-y-auto p-3">{sections.map(({ key, label, icon: Icon }) => <button key={key} onClick={() => go(key)} className={`mb-0.5 flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm font-medium transition ${section === key ? 'bg-blue-50 text-blue-800' : 'text-slate-600 hover:bg-slate-50'} ${key === 'security' ? 'mt-2 border-t border-slate-100 pt-3' : ''}`}><Icon className="h-4 w-4 shrink-0"/>{t[label]}{key === 'emergency' && <span className="ml-auto h-2 w-2 rounded-full bg-rose-500"/>}</button>)}<button onClick={onLogout} className="mt-2 flex w-full items-center gap-3 border-t border-slate-200 px-3 py-3 text-sm font-semibold text-slate-600 hover:text-rose-700"><LogOut className="h-4 w-4"/>{t.signOut}</button></nav>
      </aside>

      <main className="min-w-0 flex-1">
        <header className="sticky top-0 z-30 flex items-center justify-between border-b border-slate-200 bg-white/95 px-4 py-3 backdrop-blur sm:px-6 lg:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileNav(true)} className="rounded-lg border border-slate-200 p-2 lg:hidden" aria-label={t.navOpen}><Menu className="h-5 w-5"/></button><div className="hidden text-sm text-slate-500 sm:block">CarePulse Hospital <span className="mx-2 text-slate-300">/</span><b className="text-slate-900">{heading}</b></div></div><div className="flex items-center gap-3"><span className="hidden items-center gap-2 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-800 sm:flex"><span className="h-2 w-2 rounded-full bg-emerald-500"/>{t.operating}</span><button onClick={() => go('security')} className="relative rounded-lg p-2 text-slate-500" aria-label={t.alerts}><Bell className="h-5 w-5"/><span className="absolute right-1.5 top-1.5 h-2 w-2 rounded-full bg-rose-500"/></button><button onClick={onToggleLanguage} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold">{t.language}</button></div></header>

        <div className="mx-auto max-w-[1520px] p-4 sm:p-6 lg:p-8">
          {notice && <div role="status" className="mb-5 flex items-center gap-2 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-800"><CheckCircle2 className="h-4 w-4 shrink-0"/>{notice}</div>}

          {section === 'overview' && <>
            <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm font-semibold text-blue-700">{t.welcome}, {name}</p><h1 className="mt-1 text-3xl font-black sm:text-4xl">{t.overview}</h1><p className="mt-2 text-sm text-slate-500">{hospital.name} · {t.current}</p></div><span className="rounded-lg border border-emerald-200 bg-white px-3 py-2 text-xs font-semibold text-emerald-800">{t.operating}</span></div>
            <div className="mb-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[[t.totalPatients, '12,480', Users], [t.totalDoctors, '86', Stethoscope], [t.totalNurses, '142', HeartPulse], [t.todaysAppointments, '42', CalendarDays], [t.availableBeds, String(freeBeds + 22), Bed], [t.occupiedBeds, String(activeBeds + 70), Hospital], [t.emergencyCases, String(data.emergencies.filter((entry) => entry.status !== 'Resolved').length), AlertTriangle], [t.monthlyRevenue, 'BDT 8.4M', Wallet]].map(([label, value, Icon]) => <article key={label as string} className="rounded-xl border border-slate-200 bg-white p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-slate-500">{label as string}</p><span className="grid h-8 w-8 place-items-center rounded-lg bg-blue-50 text-blue-800">{createElement(Icon as typeof Home, { className: 'h-4 w-4' })}</span></div><p className="mt-3 text-2xl font-black">{value as string}</p></article>)}</div>
            <section className="mb-6"><h2 className="mb-3 text-xs font-bold uppercase tracking-wide text-slate-500">{t.quickAccess}</h2><div className="grid grid-cols-2 gap-3 sm:grid-cols-4 xl:grid-cols-8">{([{ key: 'patients', label: t.patients, icon: Users }, { key: 'doctors', label: t.doctors, icon: Stethoscope }, { key: 'billing', label: t.billing, icon: Wallet }, { key: 'laboratory', label: t.laboratory, icon: FlaskConical }, { key: 'pharmacy', label: t.pharmacy, icon: Pill }, { key: 'inventory', label: t.inventory, icon: Package }, { key: 'analytics', label: t.analytics, icon: Activity }, { key: 'settings', label: t.settings, icon: Settings }] as const).map(({ key, label, icon: Icon }) => <button key={key} onClick={() => go(key)} className="flex min-h-[86px] flex-col items-start justify-between rounded-xl border border-slate-200 bg-white p-3 text-left transition hover:border-blue-500"><Icon className="h-5 w-5 text-blue-800"/><span className="text-xs font-semibold">{label}</span></button>)}</div></section>
            <div className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><section className="rounded-xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold">{t.connections}</h2><p className="mt-1 text-xs text-slate-500">{t.flow}</p></div><Activity className="h-5 w-5 text-blue-700"/></div><div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-4">{[[t.linkPatient, 'patients'], [t.linkDoctor, 'doctors'], [t.linkNurse, 'hr'], [t.linkReception, 'appointments'], [t.linkLab, 'laboratory'], [t.linkPharmacy, 'pharmacy'], [t.linkAccounting, 'billing'], [t.analytics, 'analytics']].map(([label, target]) => <button key={label} onClick={() => go(target as AdminSection)} className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-3 text-left text-xs font-semibold hover:border-blue-400">{label}<span className="mt-1 block text-[10px] font-normal text-slate-500">{language === 'en' ? 'Connected' : 'সংযুক্ত'}</span></button>)}</div></section><section className="rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{t.alerts}</h2>{[[`${lowStock} ${t.lowStock}`, 'pharmacy'], [`${pendingInvoices} ${t.pending}`, 'billing'], ['ICU occupancy 88%', 'beds'], [`${data.emergencies.length} ${t.emergency}`, 'emergency']].map(([label, target]) => <button key={label} onClick={() => go(target as AdminSection)} className="mt-3 flex w-full items-center justify-between rounded-lg bg-amber-50 px-3 py-2.5 text-left text-xs font-semibold text-amber-900"><span className="flex items-center gap-2"><AlertTriangle className="h-4 w-4"/>{label}</span><span>›</span></button>)}</section></div>
            <div className="mt-5 rounded-xl border border-blue-100 bg-blue-50/70 p-4"><p className="text-xs font-semibold text-blue-900">{t.noClinical}</p></div>
          </>}

          {section === 'profile' && <section><div className="mb-5"><h1 className="text-2xl font-black">{t.profile}</h1><p className="mt-1 text-sm text-slate-500">{t.linkPatient} → Public website → Patient portal</p></div><div className="grid gap-5 xl:grid-cols-[1fr_0.8fr]"><form onSubmit={(event) => { event.preventDefault(); notify(t.settingsSaved); }} className="grid gap-3 rounded-xl border border-slate-200 bg-white p-5 sm:grid-cols-2">{([[t.hospitalName, 'name'], [t.address, 'address'], [t.phone, 'phone'], [t.email, 'email'], [t.emergencyNumber, 'emergency'], [t.website, 'website']] as const).map(([label, key]) => <label key={key} className="text-xs font-bold text-slate-500">{label}<input value={hospital[key]} onChange={(event) => setHospital({ ...hospital, [key]: event.target.value })} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm font-normal text-slate-900"/></label>)}<label className="text-xs font-bold text-slate-500 sm:col-span-2">Hospital logo<input type="file" accept="image/*" className="mt-1 block w-full rounded-lg border border-slate-300 p-2 text-sm font-normal"/></label><button className="rounded-lg bg-blue-800 px-4 py-2.5 text-sm font-bold text-white sm:col-span-2">{t.save}</button></form><section className="rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{t.facilities}</h2><div className="mt-4 space-y-2">{facilities.map((facility) => <label key={facility} className="flex items-center gap-3 rounded-lg bg-slate-50 px-3 py-2.5 text-sm"><input type="checkbox" checked onChange={() => { setFacilities((current) => current.filter((entry) => entry !== facility)); notify(t.updated); }}/>{facility}</label>)}</div><form onSubmit={(event) => { event.preventDefault(); const input = new FormData(event.currentTarget).get('facility')?.toString().trim(); if (input) setFacilities((current) => [...current, input]); event.currentTarget.reset(); }} className="mt-4 flex gap-2"><input name="facility" placeholder={t.addName} className="min-w-0 flex-1 rounded-lg border border-slate-300 px-3 py-2 text-sm"/><button className="rounded-lg bg-blue-800 px-3 text-white" aria-label={t.add}><Plus className="h-4 w-4"/></button></form></section></div></section>}

          {section === 'users' && <section><div className="mb-5"><h1 className="text-2xl font-black">{t.users}</h1><p className="mt-1 text-sm text-slate-500">{t.permissionNote}</p></div><RecordWorkspace section={section} records={filteredRecords} query={query} setQuery={setQuery} t={t} addRecord={addRecord} name={formName} setName={setFormName} detail={formDetail} setDetail={setFormDetail} updateRecord={updateRecord} actionLabel={rowActionLabel} statusLabel={statusLabel}/><section className="mt-5 rounded-xl border border-slate-200 bg-white p-5"><div className="mb-3 flex items-center justify-between"><h2 className="font-bold">{t.access}</h2><LockKeyhole className="h-5 w-5 text-blue-700"/></div><div className="divide-y divide-slate-100">{Object.entries(permissionToggles).map(([permission, checked]) => <label key={permission} className="flex items-center justify-between gap-3 py-3 text-sm"><span>{permission}</span><input type="checkbox" checked={checked} onChange={() => { setPermissionToggles((current) => ({ ...current, [permission]: !current[permission] })); notify(t.permissionChanged); }}/></label>)}</div></section></section>}

          {['doctors', 'patients', 'departments', 'appointments', 'admissions', 'beds', 'emergency', 'theatre', 'laboratory', 'pharmacy', 'inventory', 'billing', 'insurance', 'hr'].includes(section) && <section><div className="mb-5"><h1 className="text-2xl font-black">{heading}</h1><p className="mt-1 text-sm text-slate-500">{section === 'patients' ? t.patientDetails : section === 'doctors' ? t.linkDoctor : t.connections}</p>{section === 'patients' && <p className="mt-2 text-xs font-medium text-blue-800">{t.clinicalBoundary}</p>}</div><RecordWorkspace section={section} records={filteredRecords} query={query} setQuery={setQuery} t={t} addRecord={addRecord} name={formName} setName={setFormName} detail={formDetail} setDetail={setFormDetail} updateRecord={updateRecord} actionLabel={rowActionLabel} statusLabel={statusLabel}/>{section === 'beds' && <div className="mt-5 grid gap-3 sm:grid-cols-3"><Kpi label={t.availableBeds} value={String(freeBeds + 22)}/><Kpi label={t.occupiedBeds} value={String(activeBeds + 70)}/><Kpi label={t.monthlyRevenue} value="96 total beds"/></div>}{section === 'billing' && <div className="mt-4 rounded-lg bg-blue-50 p-3 text-xs text-blue-900">{t.billingNote}</div>}{section === 'pharmacy' && <div className="mt-4 rounded-lg bg-amber-50 p-3 text-xs text-amber-900">{t.inventoryNote}</div>}</section>}

          {section === 'patients' && <section className="mt-5 rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{language === 'en' ? 'Read-only clinical snapshot' : 'শুধু-পঠন ক্লিনিক্যাল সারাংশ'}</h2><p className="mt-1 text-xs text-slate-500">{t.noClinical}</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><article className="rounded-lg bg-slate-50 p-3"><b className="text-sm">Rahim Uddin · PT-1001</b><p className="mt-2 text-xs text-slate-600">{language === 'en' ? 'History: hypertension · Allergy: penicillin · Current medicine: amlodipine' : 'ইতিহাস: উচ্চ রক্তচাপ · অ্যালার্জি: পেনিসিলিন · বর্তমান ওষুধ: অ্যামলোডিপিন'}</p></article><article className="rounded-lg bg-slate-50 p-3"><b className="text-sm">Ayesha Rahman · PT-1002</b><p className="mt-2 text-xs text-slate-600">{language === 'en' ? 'History: asthma · No known drug allergy · Current medicine: salbutamol inhaler' : 'ইতিহাস: হাঁপানি · ওষুধে পরিচিত অ্যালার্জি নেই · বর্তমান ওষুধ: সালবিউটামল ইনহেলার'}</p></article></div></section>}

          {section === 'analytics' && <section><div className="mb-5"><h1 className="text-2xl font-black">{t.analytics}</h1><p className="mt-1 text-sm text-slate-500">{t.reportDisclaimer}</p></div><div className="grid gap-4 xl:grid-cols-2"><Chart title={t.patientGrowth} values={[38, 50, 46, 65, 57, 76, 88]}/><Chart title={t.revenue} values={[48, 60, 55, 72, 69, 82, 94]}/><Chart title={t.departmentLoad} values={[82, 64, 53, 44, 39, 27, 20]}/><Chart title={t.bedOccupancy} values={[62, 68, 72, 70, 76, 79, 75]}/></div><article className="mt-4 rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{t.doctorPerformance}</h2>{data.doctors.map((doctor, index) => <div key={doctor.id} className="mt-4"><div className="mb-1 flex justify-between text-xs"><span>{doctor.name}</span><b>{[92, 86, 82, 78][index] ?? 74}%</b></div><div className="h-2 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-emerald-600" style={{ width: `${[92, 86, 82, 78][index] ?? 74}%` }}/></div></div>)}</article></section>}

          {section === 'security' && <section><div className="mb-5"><h1 className="text-2xl font-black">{t.security}</h1><p className="mt-1 text-sm text-slate-500">{t.securityTitle}</p></div><div className="grid gap-4 xl:grid-cols-[0.8fr_1.2fr]"><article className="rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{t.loginSecurity}</h2><label className="mt-4 flex items-center justify-between gap-3 border-b border-slate-100 py-3 text-sm"><span>{t.twoFactor}</span><input type="checkbox" checked={twoFactor} onChange={() => setTwoFactor((value) => !value)}/></label><label className="flex items-center justify-between gap-3 py-3 text-sm"><span>{t.sessionTimeout}</span><input type="checkbox" checked={timeout} onChange={() => setTimeout((value) => !value)}/></label><button onClick={() => notify(t.backupDone)} className="mt-4 inline-flex items-center gap-2 rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold"><FileText className="h-4 w-4"/>{t.backup}</button></article><article className="rounded-xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><h2 className="font-bold">{t.audit}</h2><ShieldCheck className="h-5 w-5 text-blue-700"/></div><div className="mt-3 divide-y divide-slate-100">{audit.map((entry, index) => <div key={`${entry.time}-${index}`} className="flex flex-wrap justify-between gap-2 py-3 text-sm"><span>{entry.action}</span><small className="text-slate-500">{entry.time}</small></div>)}</div></article></div></section>}

          {section === 'settings' && <section><div className="mb-5"><h1 className="text-2xl font-black">{t.settings}</h1></div><div className="max-w-3xl rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{t.access}</h2><p className="mt-2 text-sm text-slate-600">{t.permissionNote}</p><div className="mt-4 rounded-lg bg-slate-50 p-4 text-sm">{t.noClinical}</div><button onClick={() => notify(t.settingsSaved)} className="mt-4 rounded-lg bg-blue-800 px-4 py-2.5 text-sm font-bold text-white">{t.save}</button></div></section>}

          <p className="mt-6 text-[11px] leading-5 text-slate-400">{t.demo}</p>
        </div>
        <aside className="fixed bottom-4 right-4 z-20 w-[min(350px,calc(100%-2rem))] overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.16)] sm:bottom-6 sm:right-6"><div className="flex items-center gap-2 border-b border-slate-100 px-4 py-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-blue-50 text-blue-800"><Activity className="h-4 w-4"/></span><div><b className="block text-sm">{t.aiAssistant}</b><small className="text-[10px] text-slate-500">{t.assistantDisclaimer}</small></div><button onClick={() => setAiAnswer((current) => current ? '' : t.assistantDefault)} className="ml-auto px-2 text-lg font-bold text-blue-800" aria-label={t.ask}>+</button></div>{aiAnswer && <p className="px-4 pt-3 text-xs leading-5 text-slate-700">{aiAnswer}</p>}<form onSubmit={decideAssistant} className="flex gap-2 p-3"><input value={aiQuestion} onChange={(event) => setAiQuestion(event.target.value)} placeholder={t.askPlaceholder} className="min-w-0 flex-1 rounded-lg border border-slate-200 px-3 py-2 text-xs outline-none focus:border-blue-600"/><button className="rounded-lg bg-blue-800 px-3 text-xs font-bold text-white">{t.ask}</button></form></aside>
      </main>
    </div>
  );
}

function Kpi({ label, value }: { label: string; value: string }) {
  return <article className="rounded-xl border border-slate-200 bg-white p-4"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-xl font-black">{value}</p></article>;
}

function Chart({ title, values }: { title: string; values: number[] }) {
  return <article className="rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">{title}</h2><div className="mt-5 flex h-44 items-end gap-2 border-b border-slate-200">{values.map((value, index) => <div key={index} className="flex h-full flex-1 flex-col justify-end"><div className="rounded-t bg-blue-600" style={{ height: `${value}%` }}/><span className="py-2 text-center text-[10px] text-slate-500">{['M','T','W','T','F','S','S'][index]}</span></div>)}</div></article>;
}

function RecordWorkspace({ section, records, query, setQuery, t, addRecord, name, setName, detail, setDetail, updateRecord, actionLabel, statusLabel }: {
  section: AdminSection; records: Row[]; query: string; setQuery: (value: string) => void; t: Record<string, string>;
  addRecord: (event: FormEvent) => void; name: string; setName: (value: string) => void; detail: string; setDetail: (value: string) => void;
  updateRecord: (id: string, changes?: Partial<Row>) => void; actionLabel: (record: Row) => string; statusLabel: (status: string) => string;
}) {
  const [editingId, setEditingId] = useState('');
  const [draftName, setDraftName] = useState('');
  const [draftDetail, setDraftDetail] = useState('');
  const allowAdd = ['users', 'doctors', 'patients', 'departments', 'appointments', 'admissions', 'beds', 'emergency', 'theatre', 'laboratory', 'pharmacy', 'inventory', 'billing', 'insurance', 'hr'].includes(section);
  const canManage = ['users', 'doctors', 'departments', 'patients'].includes(section);
  const canRemove = ['users', 'doctors', 'departments'].includes(section);
  const roleOptions = ['Doctor', 'Nurse', 'Receptionist', 'Accountant', 'Laboratory staff', 'Pharmacy staff', 'Administrator', 'HR staff'];

  return <section className="overflow-hidden rounded-xl border border-slate-200 bg-white">
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 p-4"><div><h2 className="font-bold">{t.recentActivity}</h2><p className="mt-1 text-xs text-slate-500">{records.length} · {t.current}</p></div><label className="relative w-full sm:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t.searchHint} className="w-full rounded-lg border border-slate-300 py-2 pl-9 pr-3 text-sm"/></label></div>
    {allowAdd && <form onSubmit={addRecord} className="grid gap-2 border-b border-slate-200 bg-slate-50 p-4 sm:grid-cols-[1fr_1.3fr_auto]"><input required value={name} onChange={(event) => setName(event.target.value)} placeholder={t.addName} className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"/><input value={detail} onChange={(event) => setDetail(event.target.value)} placeholder={t.addDetail} className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"/><button className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-800 px-3 py-2 text-sm font-bold text-white"><Plus className="h-4 w-4"/>{t.add}</button></form>}
    <div className="divide-y divide-slate-100">{records.map((record) => <article key={record.id} className="flex flex-wrap items-center justify-between gap-3 px-4 py-4"><div className="flex min-w-0 flex-1 items-center gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-blue-50 text-blue-800"><FileText className="h-4 w-4"/></span>{editingId === record.id ? <div className="grid min-w-0 flex-1 gap-2 sm:grid-cols-2"><input aria-label={t.fullName} value={draftName} onChange={(event) => setDraftName(event.target.value)} className="rounded-lg border border-slate-300 px-3 py-2 text-sm"/><input aria-label={t.addDetail} value={draftDetail} onChange={(event) => setDraftDetail(event.target.value)} className="rounded-lg border border-slate-300 px-3 py-2 text-sm"/><div className="flex gap-2"><button onClick={() => { updateRecord(record.id, { name: draftName, detail: draftDetail }); setEditingId(''); }} className="rounded-lg bg-blue-800 px-3 py-1.5 text-xs font-bold text-white">{t.save}</button><button onClick={() => setEditingId('')} className="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-semibold">{languageLabel(t, 'cancel')}</button></div></div> : <div className="min-w-0"><p className="truncate text-sm font-bold">{record.name} <span className="font-normal text-slate-400">· {record.id}</span></p><p className="mt-1 text-xs text-slate-500">{record.detail}</p></div>}</div><div className="ml-12 flex flex-wrap items-center gap-2 sm:ml-0"><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${record.status === 'Critical' || record.status === 'Low stock' || record.status === 'Pending' || record.status === 'Pending approval' ? 'bg-amber-50 text-amber-800' : record.status === 'Paid' || record.status === 'Available' || record.status === 'Active' || record.status === 'Approved' ? 'bg-emerald-50 text-emerald-800' : 'bg-slate-100 text-slate-700'}`}>{statusLabel(record.status)}</span>{section === 'users' && <select aria-label={`${t.role} ${record.name}`} value={record.detail.split('·')[0].trim()} onChange={(event) => updateRecord(record.id, { detail: `${event.target.value} · ${record.detail.split('·').slice(1).join('·').trim()}` })} className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs">{roleOptions.map((role) => <option key={role}>{role}</option>)}</select>}{editingId !== record.id && canManage && <button onClick={() => { setEditingId(record.id); setDraftName(record.name); setDraftDetail(record.detail); }} className="rounded-lg border border-slate-300 px-2.5 py-1.5 text-xs font-semibold">{languageLabel(t, 'edit')}</button>}{editingId !== record.id && canRemove && <button onClick={() => updateRecord(record.id, { status: 'Archived' })} className="rounded-lg border border-rose-200 px-2.5 py-1.5 text-xs font-semibold text-rose-700">{languageLabel(t, 'remove')}</button>}<button onClick={() => updateRecord(record.id)} className="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-semibold hover:border-blue-600 hover:text-blue-800">{actionLabel(record)}</button></div></article>)}{records.length === 0 && <p className="p-8 text-center text-sm text-slate-500">{t.noRecords}</p>}</div>
  </section>;
}

function languageLabel(t: Record<string, string>, key: 'edit' | 'remove' | 'cancel') {
  const bnLabels = { edit: 'সম্পাদনা', remove: 'সরান', cancel: 'বাতিল' };
  const enLabels = { edit: 'Edit', remove: 'Remove', cancel: 'Cancel' };
  return t.language === 'EN' ? bnLabels[key] : enLabels[key];
}